// The page and its plain-text twin. Static HTML regenerated by the tool; the
// page fetches itself on a timer and swaps its table in, so a browser tab
// left open follows along without losing the reader's place.

// legendEntry is one state word and what it means.
type legendEntry struct {
	state worktree.State
	means string
}

// legendEntries is what the nine state words mean, for the reader of the page
// (the design's table in docs/design/cli-1.0.md, "State words", in a clause
// each), in the order the states are decided.
var legendEntries = []legendEntry{
	{worktree.StateRemoving, "a removal was interrupted: 'treerig worktree remove' finishes it."},
	{worktree.StateDirectoryMissing, "Git no longer has the worktree's directory."},
	{worktree.StateUnknown, "treerig couldn't tell (Docker or Git didn't answer, or a record couldn't be read); the row says why."},
	{worktree.StateStarting, "a health check has not passed yet."},
	{worktree.StateFailed, "no service runs, and one exited with an error, keeps restarting or is unhealthy."},
	{worktree.StatePartlyRunning, "some services run and others don't."},
	{worktree.StateRunning, "every service that has not finished is up."},
	{worktree.StateStopped, "'treerig up' has finished before, and nothing runs now."},
	{worktree.StateNotStarted, "'treerig up' has not finished yet."},
}

// legendHTML is the legend as a definition list, one entry a line.
func legendHTML() string {
	var b strings.Builder
	b.WriteString(`<dl class="legend">`)
	for _, entry := range legendEntries {
		fmt.Fprintf(&b, "<div><dt>%s</dt> <dd>%s</dd></div>", escapeHTML(entry.state.String()), escapeHTML(entry.means))
	}
	b.WriteString("</dl>")
	return b.String()
}

// legendText is the legend for the text twin: a line to an entry, folded
// under its word where it is long.
func legendText() string {
	lines := make([]string, len(legendEntries))
	for i, entry := range legendEntries {
		lines[i] = strings.ReplaceAll(wrapText(entry.state.String()+": "+entry.means, textWidth), "\n", "\n  ")
	}
	return strings.Join(lines, "\n")
}

// stateClass is the CSS class suffix of a state's pill: its JSON word with
// hyphens, so `partly running` is `status-partly-running`.
func stateClass(state worktree.State) string {
	return strings.ReplaceAll(state.JSON(), "_", "-")
}

// noscriptRefreshSeconds: without scripting there is nothing to swap, so the
// whole page reloads instead. A meta refresh cannot be paused, which WCAG
// 2.2.1 asks for; the scripted path has the button, and this is the only way
// a page with no scripting can follow a machine that keeps changing.
const noscriptRefreshSeconds = 60

// script and styles are the exact JavaScript and CSS a browser runs to keep
// the index page live-updating without a reload: this text is executed
// as-is by the browser, so it cannot be regenerated from Go source, only
// edited directly and kept in step with planIndexUpdate below, which pins
// its parsing logic under ordinary Go tests. Their origin is in git
// history.
//
//go:embed assets/script.js
var script string

//go:embed assets/styles.css
var styles string

// scriptHash and shellFingerprint depend only on the embedded assets above,
// which never change at runtime, so they are computed once, here, rather
// than on every render.
var (
	scriptHash       = base64.StdEncoding.EncodeToString(sum256(script))
	shellFingerprint = base64.RawURLEncoding.EncodeToString(sum256(styles + script))[:16]
	faviconLinks     = renderFaviconLinks()
)

// sum256 is the raw SHA-256 digest of value, as a byte slice ready for a
// base64 encoder.
func sum256(value string) []byte {
	sum := sha256.Sum256([]byte(value))
	return sum[:]
}

var htmlEscaper = strings.NewReplacer(
	"&", "&amp;",
	"<", "&lt;",
	">", "&gt;",
	`"`, "&quot;",
	"'", "&#39;",
)

// escapeHTML escapes value for embedding in the page, through Printable
// first: escaping stops markup, not a right-to-left override that reverses
// the rest of a row, or a zero-width space that makes two checkouts look
// identical.
func escapeHTML(value string) string {
	return htmlEscaper.Replace(text.Printable(value))
}

// compactPath is "/Users/me/dev/x" -> "~/dev/x"; paths outside home are left
// alone.
func compactPath(target, home string) string {
	rel, err := filepath.Rel(home, target)
	// filepath.Rel gives "." where Node's path.relative gives "" for two
	// equal paths; both mean "this is not a path under home worth showing
	// relative to it".
	if err != nil || rel == "." || strings.HasPrefix(rel, "..") || filepath.IsAbs(rel) {
		return target
	}
	return filepath.Join("~", rel)
}

// userHomeDir resolves the current user's home directory. A var, not a
// direct call to os.UserHomeDir, so a test can pin it to a fixed value: a
// test that both sets up the expectation and exercises the row-rendering
// code by calling compactPath against the real environment's home directory
// can never catch a regression in compactPath, since both sides would be
// wrong together.
var userHomeDir = os.UserHomeDir

// homeDir is the current user's home directory, compactPath's default at
// its two production call sites; "" (compactPath's harmless no-match) if it
// cannot be read.
func homeDir() string {
	home, err := userHomeDir()
	if err != nil {
		return ""
	}
	return home
}

// indexSection is one whole table: every row of one domain, headed by its
// project names (or the domain alone).
type indexSection struct {
	Heading string
	Entries []IndexEntry
}

// groupAndHeadSections is groupByDomain plus domainHeading: every row of one
// domain together, in the order the snapshot sorted them, headed by its
// project's name beside its domain — or the domain alone, when no card has
// named the project. Grouping is by domain rather than project so a
// checkout whose first `up` never finished, and which therefore has no card
// to name its project, joins its project's table instead of starting a
// second one.
func groupAndHeadSections(entries []IndexEntry) []indexSection {
	order := make([]string, 0, len(entries))
	groups := make(map[string][]IndexEntry, len(entries))
	for _, entry := range entries {
		if _, ok := groups[entry.Domain]; !ok {
			order = append(order, entry.Domain)
		}
		groups[entry.Domain] = append(groups[entry.Domain], entry)
	}
	result := make([]indexSection, len(order))
	for i, domain := range order {
		result[i] = indexSection{Heading: domainHeading(domain, groups[domain]), Entries: groups[domain]}
	}
	return result
}

// domainHeading is the project's name beside its domain — or the domain
// alone, when no card has named a project other than the domain itself.
// Every distinct project on the domain is listed, sorted and joined with
// ", ", so a domain shared by several projects names all of them.
func domainHeading(domain string, entries []IndexEntry) string {
	seen := make(map[string]struct{}, len(entries))
	var named []string
	for _, entry := range entries {
		if entry.Project == domain {
			continue
		}
		if _, ok := seen[entry.Project]; ok {
			continue
		}
		seen[entry.Project] = struct{}{}
		named = append(named, entry.Project)
	}
	slices.SortStableFunc(named, text.Collate)
	if len(named) == 0 {
		return domain
	}
	return strings.Join(named, ", ") + " · " + domain
}

// sections groups entries into whole tables, in the order their headings
// read — which is not the order their domains sort in.
func sections(entries []IndexEntry) []indexSection {
	result := groupAndHeadSections(entries)
	slices.SortStableFunc(result, func(left, right indexSection) int {
		return text.Collate(left.Heading, right.Heading)
	})
	return result
}

// renderRow is one <tr> of the overview: the branch (or a placeholder when
// nothing recorded one), the host, the directory, the state pill with its
// guidance, and every declared service. unchecked
// means Docker could not be asked, so a service link is shown live rather
// than greyed out — nothing has actually confirmed it is unavailable.
func renderRow(entry IndexEntry, unchecked bool) string {
	// Nothing was asked of a worktree Git says has lost its directory; its
	// services are not "not answering", they are not there.
	gone := entry.State == worktree.StateDirectoryMissing
	compact := ""
	if entry.Root != "" {
		compact = compactPath(entry.Root, homeDir())
	}
	checkout := `<span class="muted">—</span>`
	if entry.Root != "" {
		checkout = fmt.Sprintf(`<span class="path" title="%s">%s</span>`, escapeHTML(entry.Root), escapeHTML(compact))
	}
	services := `<span class="muted">—</span>`
	if len(entry.Services) > 0 {
		items := make([]string, len(entry.Services))
		for i, service := range entry.Services {
			contents := fmt.Sprintf(`<span class="service-label">%s</span><span class="service-purpose">%s</span>`,
				escapeHTML(service.Label), escapeHTML(service.Purpose))
			target := escapeHTML(entry.Host + "-" + service.Name)
			switch {
			case unchecked:
				// Nothing checked these, so the link is the only way left to
				// find out: never grey out a service whose state nobody has
				// actually read.
				items[i] = fmt.Sprintf(`<li><a class="service-link" href="%s" target="%s" title="%s">%s<span class="sr-only"> (state unknown)</span></a></li>`,
					escapeHTML(service.URL), target, escapeHTML(service.URL), contents)
			case service.Available:
				items[i] = fmt.Sprintf(`<li><a class="service-link" href="%s" target="%s" title="%s">%s</a></li>`,
					escapeHTML(service.URL), target, escapeHTML(service.URL), contents)
			default:
				// A screen reader gets the word; sighted readers get the grey.
				unavailable := " (unavailable)"
				if gone {
					unavailable = " (directory missing)"
				}
				items[i] = fmt.Sprintf(`<li><span class="service-link service-disabled" title="%s">%s<span class="sr-only">%s</span></span></li>`,
					escapeHTML(service.URL), contents, unavailable)
			}
		}
		// An explicit role: WebKit drops a bulletless list's role otherwise.
		services = `<ul role="list">` + strings.Join(items, "") + `</ul>`
	}
	guidance := ""
	switch entry.State {
	case worktree.StateDirectoryMissing:
		guidance = fmt.Sprintf(`<div class="guidance">Git no longer has its directory, so run <code>%s worktree remove %s</code></div>`,
			escapeHTML(brand.Name), escapeHTML(entry.Slug))
	case worktree.StateRemoving:
		guidance = fmt.Sprintf(`<div class="guidance">A removal was interrupted — <code>%s worktree remove %s</code> finishes it</div>`,
			escapeHTML(brand.Name), escapeHTML(entry.Slug))
	case worktree.StateUnknown:
		if entry.Hint != "" {
			guidance = fmt.Sprintf(`<div class="guidance">%s</div>`, escapeHTML(entry.Hint))
		}
	}
	described := DescribeBranch(entry.Branch)
	name := fmt.Sprintf(`<strong>%s</strong>`, escapeHTML(described.Text))
	if described.Muted {
		name = fmt.Sprintf(`<span class="muted">%s</span>`, escapeHTML(described.Text))
	}
	echo := ""
	if compact != "" {
		echo = fmt.Sprintf(`<span class="path-compact">%s</span>`, escapeHTML(compact))
	}
	return fmt.Sprintf(`<tr>
      <th scope="row">%s%s<span class="host-compact"><code>%s</code></span></th>
      <td class="host"><code>%s</code></td>
      <td class="checkout">%s</td>
      <td><span class="status status-%s">%s</span>%s</td>
      <td class="services">%s</td>
    </tr>`, name, echo, escapeHTML(entry.Host), escapeHTML(entry.Host), checkout,
		escapeHTML(stateClass(entry.State)), escapeHTML(entry.State.String()), guidance, services)
}

// renderSharedSection is the page's group of shared-service web UIs, beneath
// the checkouts: one row per routed service, with the project it belongs to
// and a link to its address. unchecked means Docker could not be asked, so a
// link is shown live rather than greyed out, as for a checkout's services. It
// is empty when there are none, so a page without shared services is
// unchanged.
func renderSharedSection(services []IndexSharedService, unchecked bool) string {
	if len(services) == 0 {
		return ""
	}
	rows := make([]string, len(services))
	for i, service := range services {
		contents := fmt.Sprintf(`<span class="service-label">%s</span><span class="service-purpose">%s</span>`,
			escapeHTML(service.Name), escapeHTML(service.Host))
		link := ""
		if unchecked || service.Available {
			note := ""
			if unchecked {
				note = `<span class="sr-only"> (state unknown)</span>`
			}
			link = fmt.Sprintf(`<a class="service-link" href="%s" target="%s" title="%s">%s%s</a>`,
				escapeHTML(service.URL), escapeHTML(service.Host), escapeHTML(service.URL), contents, note)
		} else {
			link = fmt.Sprintf(`<span class="service-link service-disabled" title="%s">%s<span class="sr-only"> (unavailable)</span></span>`,
				escapeHTML(service.URL), contents)
		}
		rows[i] = fmt.Sprintf(`<tr>
      <th scope="row"><strong>%s</strong></th>
      <td>%s</td>
      <td class="services"><ul role="list"><li>%s</li></ul></td>
    </tr>`, escapeHTML(service.Name), escapeHTML(service.Project), link)
	}
	return fmt.Sprintf(`
    <section>
      <h2 id="shared-services">Shared services</h2>
      <div class="table-wrap" role="region" aria-labelledby="shared-services">
        <table>
          <thead><tr><th scope="col">Service</th><th scope="col">Project</th><th scope="col">Web UI</th></tr></thead>
          <tbody>%s</tbody>
        </table>
      </div>
    </section>`, strings.Join(rows, "\n"))
}

// pageTitle is `Worktrees (3)` — the count is what tells one pinned tab from
// another. The live-update script assigns this straight to document.title,
// so it must stay text that reads the same escaped or not.
func pageTitle(snapshot IndexSnapshot) string {
	return fmt.Sprintf("Worktrees (%d)", len(snapshot.Entries))
}

// indexUpdateKind is what a freshly fetched copy of the page means for the
// copy on screen.
type indexUpdateKind string

const (
	indexUpdateUnchanged indexUpdateKind = "unchanged"
	// indexUpdateForeign is a document planIndexUpdate did not write, or one
	// cut short — distinct from unchanged, so a tab can tell "nothing to do"
	// from "whatever answered is not the index".
	indexUpdateForeign indexUpdateKind = "foreign"
	indexUpdateReady   indexUpdateKind = "update"
)

// indexUpdate is planIndexUpdate's result. Stamp, Title, Main, Shell and
// Body are populated only when Kind is indexUpdateReady.
type indexUpdate struct {
	Kind  indexUpdateKind
	Stamp string
	Title string
	Main  string
	Shell string
	Body  string
}

// indexOfFrom is JavaScript's String.prototype.indexOf(substr, from): the
// first index of substr at or after from, or -1, exactly as
// planIndexUpdate's own html.indexOf(tag, from) call needs it to behave.
func indexOfFrom(s, substr string, from int) int {
	if from < 0 {
		from = 0
	}
	if from > len(s) {
		return -1
	}
	if i := strings.Index(s[from:], substr); i >= 0 {
		return from + i
	}
	return -1
}

// planIndexUpdate mirrors the identically named browser function embedded
// in the page as text (internal/checkoutindex/assets/script.js), kept here
// so its parsing logic is pinned by ordinary Go tests. Production Go code
// never calls this — the page runs the embedded script itself — but this
// must keep parsing a rendered page exactly as that script does, since
// both read the same bytes.
func planIndexUpdate(current *string, html string) indexUpdate {
	const mainOpen = "<" + "main"
	const mainClose = "</" + "main>"
	const titleOpen = "<" + "title>"
	const titleClose = "</" + "title>"
	const stampTag = "<" + `time datetime="`
	const shellTag = "data-" + `shell="`
	const bodyTag = "data-" + `body="`

	// An attribute value, refused when the tag ends before the closing
	// quote: a response cut mid-attribute must not read as the rest of the
	// document.
	value := func(tag string, from int) (string, bool) {
		at := indexOfFrom(html, tag, from)
		if at < 0 {
			return "", false
		}
		quote := indexOfFrom(html, `"`, at+len(tag))
		tagEnd := indexOfFrom(html, ">", at+len(tag))
		if quote < 0 || (tagEnd >= 0 && tagEnd < quote) {
			return "", false
		}
		return html[at+len(tag) : quote], true
	}

	mainAt := indexOfFrom(html, mainOpen, 0)
	titleAt := indexOfFrom(html, titleOpen, 0)
	if mainAt < 0 || titleAt < 0 {
		return indexUpdate{Kind: indexUpdateForeign}
	}
	mainTagEnd := indexOfFrom(html, ">", mainAt)
	mainEnd := indexOfFrom(html, mainClose, mainAt)
	titleEnd := indexOfFrom(html, titleClose, titleAt)
	stamp, hasStamp := value(stampTag, 0)
	shell, hasShell := value(shellTag, 0)
	body, hasBody := value(bodyTag, mainAt)
	if mainTagEnd < 0 || mainEnd < mainTagEnd || titleEnd < 0 {
		return indexUpdate{Kind: indexUpdateForeign}
	}
	if !hasStamp || stamp == "" || !hasShell || !hasBody {
		return indexUpdate{Kind: indexUpdateForeign}
	}
	if current != nil && stamp == *current {
		return indexUpdate{Kind: indexUpdateUnchanged}
	}
	return indexUpdate{
		Kind:  indexUpdateReady,
		Stamp: stamp,
		Shell: shell,
		Body:  body,
		Title: html[titleAt+len(titleOpen) : titleEnd],
		Main:  html[mainTagEnd+1 : mainEnd],
	}
}

// dockerNotice: Docker could not be asked, so nothing below was checked —
// except that a directory is gone or a removal is under way, which Git and the
// registry answer on their own and the page still shows.
func dockerNotice(reason *string) string {
	said := ""
	if reason != nil {
		said = ": " + *reason
		// Docker's own words may end a sentence already.
		if !strings.HasSuffix(said, ".") && !strings.HasSuffix(said, "?") && !strings.HasSuffix(said, "!") {
			said += "."
		}
	} else {
		said = "."
	}
	return "Docker could not be asked about containers, so no service below has been checked" + said + " " +
		fmt.Sprintf("Rows show unknown unless their directory is missing or their removal is under way. Run `%s index` again once it answers.", brand.Name)
}

// identityNotice explains what a failed Git lookup cost the page: whether
// the affected rows show unknown, or whether none could be called directory
// missing at all, depending on what failure says was checked.
func identityNotice(failure IdentityFailure) string {
	// Whatever Git said is prose, not markup: its own backticks would
	// otherwise pair with this sentence's and wrap the wrong span in a code
	// span.
	reason := strings.ReplaceAll(failure.Reason, "`", "'")
	consequence := "No worktree below could be compared against it, so none is reported as having lost its directory."
	if failure.RowsUnknown {
		consequence = "Its worktrees show unknown rather than directory missing."
	}
	return fmt.Sprintf("Git could not be asked about the repository that last regenerated this page — %s. %s "+
		"Run `%s index` from one of its worktrees once Git can list them again.", reason, consequence, brand.Name)
}

// cardReadFailureNotice explains what #18's distinguishable read failures
// cost the page: count worktrees show unknown not because they never
// published a card, but because theirs could not be read this time.
func cardReadFailureNotice(count int) string {
	if count == 1 {
		return fmt.Sprintf("One worktree's index card could not be read, so its state shows unknown. "+
			"Run `%s index` again once whatever blocked the read (often too many open files "+
			"at once) has cleared.", brand.Name)
	}
	return fmt.Sprintf("%d worktrees' index cards could not be read, so their state shows unknown. "+
		"Run `%s index` again once whatever blocked the read (often too many open files "+
		"at once) has cleared.", count, brand.Name)
}

// emptyState is what there is to say when no worktree has ever been indexed.
func emptyState() string {
	return fmt.Sprintf("No worktrees have been indexed yet. Run `%s up` in a worktree.", brand.Name)
}

var codeSpanPattern = regexp.MustCompile("`([^`]+)`")

// withCode is backticked command spans, the one piece of markup these
// notices carry.
func withCode(value string) string {
	return codeSpanPattern.ReplaceAllString(escapeHTML(value), "<code>$1</code>")
}

// RenderIndexHTML renders the checkout index page as HTML.
func RenderIndexHTML(snapshot IndexSnapshot) string {
	// The id counts sections rather than naming the domain: a registry
	// record's domain is not validated as a hostname, and a space in one
	// would make the reference two tokens that name nothing.
	tableSections := sections(snapshot.Entries)
	tableStrings := make([]string, len(tableSections))
	for index, section := range tableSections {
		id := fmt.Sprintf("checkouts-%d", index)
		rows := make([]string, len(section.Entries))
		for i, entry := range section.Entries {
			rows[i] = renderRow(entry, !snapshot.DockerReachable && entry.State != worktree.StateDirectoryMissing)
		}
		tableStrings[index] = fmt.Sprintf(`
    <section>
      <h2 id="%[1]s">%[2]s</h2>
      <!-- The script makes this focusable if it ever scrolls; a region that
           does not scroll would only be a tab stop that does nothing. -->
      <div class="table-wrap" role="region" aria-labelledby="%[1]s">
        <table>
          <thead><tr><th scope="col">Branch</th><th scope="col" class="host">Host</th><th scope="col" class="checkout">Directory</th><th scope="col">State</th><th scope="col">Services</th></tr></thead>
          <tbody>%[3]s</tbody>
        </table>
      </div>
    </section>`, id, escapeHTML(section.Heading), strings.Join(rows, "\n"))
	}
	tables := strings.Join(tableStrings, "\n")

	var notices []string
	if !snapshot.DockerReachable {
		notices = append(notices, dockerNotice(snapshot.DockerError))
	}
	if snapshot.IdentityError != nil {
		notices = append(notices, identityNotice(*snapshot.IdentityError))
	}
	if snapshot.CardReadFailures > 0 {
		notices = append(notices, cardReadFailureNotice(snapshot.CardReadFailures))
	}
	var noticesHTML strings.Builder
	for _, notice := range notices {
		fmt.Fprintf(&noticesHTML, `<p class="notice">%s</p>`, withCode(notice))
	}

	// One legend for the page, above the tables: the same five words
	// explain every project, and a reader should not have to scroll to find
	// them. Both notices describe the rows, so neither is said when there
	// are none.
	body := fmt.Sprintf(`<p class="empty">%s</p>`, withCode(emptyState()))
	if len(snapshot.Entries) > 0 {
		body = fmt.Sprintf(`%s%s%s`, noticesHTML.String(), legendHTML(), tables)
	}
	if len(snapshot.Shared) > 0 {
		body += renderSharedSection(snapshot.Shared, !snapshot.DockerReachable)
	}

	// What the rows say, so a tab can tell a regeneration that changed
	// something from one that only moved the clock — on its very first
	// poll, which a remembered copy of the last fetch cannot do. Hashed
	// over exactly what lands between the tags, so a tab comparing this
	// against what it fetched is comparing the same bytes.
	rows := body + "\n  "
	fingerprint := base64.RawURLEncoding.EncodeToString(sum256(rows))[:16]

	return fmt.Sprintf(`<!doctype html>
<html lang="en" data-shell="%s">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; script-src 'sha256-%s'; connect-src 'self'; form-action 'none'; base-uri 'none'">
  <noscript><meta http-equiv="refresh" content="%d"></noscript>
  %s
  <title>%s</title>
  <style>%s  </style>
</head>
<body>
  <header>
    <h1>Worktrees</h1>
    <p class="updated">Updated <time datetime="%s">%s</time> <span class="stale" id="index-stale" role="status"></span></p>
  </header>
  <p class="sr-only" id="index-announcer" aria-live="polite"></p>
  <main data-body="%s">%s</main>
  <script>%s</script>
</body>
</html>
`, shellFingerprint, scriptHash, noscriptRefreshSeconds, faviconLinks, escapeHTML(pageTitle(snapshot)), styles,
		escapeHTML(snapshot.GeneratedAt), escapeHTML(snapshot.GeneratedAt), fingerprint, rows, script)
}

// PlaceholderHTML is the page to write before anything has been read: no
// checkouts, and Docker not asked. The router (#39) serves this while it
// brings itself up, long before a container has been listed.
func PlaceholderHTML(now time.Time) string {
	return RenderIndexHTML(PlaceholderSnapshot(now.UTC().Format("2006-01-02T15:04:05.000Z")))
}

// wrapText folds at spaces to fit a terminal. A word longer than the width
// is left whole.
func wrapText(value string, width int) string {
	var lines []string
	line := ""
	for _, word := range strings.Split(value, " ") {
		candidate := word
		if line != "" {
			candidate = line + " " + word
		}
		if text.JSLen(candidate) > width && line != "" {
			lines = append(lines, line)
			line = word
		} else {
			line = candidate
		}
	}
	if line != "" {
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}

// textWidth is what prose folds at; a path or a URL never does, because a
// reader has to be able to copy one off the line whole.
const textWidth = 78

// Service state markers: "!" is a state that was read, "?" one that could
// not be, "-" a worktree whose directory is gone.
const (
	markerAvailable   = "  "
	markerUnavailable = "! "
	markerUnchecked   = "? "
	markerGone        = "- "
)

// FormatIndexText renders the overview as plain text, the plain-text
// twin of RenderIndexHTML.
func FormatIndexText(snapshot IndexSnapshot, url string) string {
	textSections := sections(snapshot.Entries)
	groupStrings := make([]string, len(textSections))
	for i, section := range textSections {
		rowStrings := make([]string, len(section.Entries))
		for j, entry := range section.Entries {
			rowStrings[j] = formatIndexRow(entry, snapshot.DockerReachable)
		}
		groupStrings[i] = wrapText(text.Printable(section.Heading), textWidth) + "\n" + strings.Join(rowStrings, "\n\n")
	}
	groups := strings.Join(groupStrings, "\n\n")

	head := fmt.Sprintf("Overview  %s\nUpdated   %s\n", text.Printable(url), text.Printable(snapshot.GeneratedAt))
	if len(snapshot.Entries) == 0 {
		empty := head + "\n" + wrapText(emptyState(), textWidth)
		if len(snapshot.Shared) > 0 {
			return empty + formatSharedText(snapshot) + "\nShared services: ! not answering, ? not checked."
		}
		return empty
	}
	var notices strings.Builder
	if !snapshot.DockerReachable {
		fmt.Fprintf(&notices, "%s\n\n", wrapText(text.Printable(dockerNotice(snapshot.DockerError)), textWidth))
	}
	if snapshot.IdentityError != nil {
		fmt.Fprintf(&notices, "%s\n\n", wrapText(text.Printable(identityNotice(*snapshot.IdentityError)), textWidth))
	}
	if snapshot.CardReadFailures > 0 {
		fmt.Fprintf(&notices, "%s\n\n", wrapText(text.Printable(cardReadFailureNotice(snapshot.CardReadFailures)), textWidth))
	}
	legend := legendText() + "\nServices: ! not answering, ? not checked, - directory missing.\n\n"
	return head + "\n" + notices.String() + legend + groups + formatSharedText(snapshot)
}

// formatSharedText is the plain-text twin of renderSharedSection: a heading
// and, per service, its name and project and the address on a line of its
// own, which is never wrapped so it can be copied. Empty when there are none.
func formatSharedText(snapshot IndexSnapshot) string {
	if len(snapshot.Shared) == 0 {
		return ""
	}
	lines := make([]string, 0, len(snapshot.Shared)+1)
	lines = append(lines, "Shared services")
	for _, service := range snapshot.Shared {
		marker := markerAvailable
		switch {
		case !snapshot.DockerReachable:
			marker = markerUnchecked
		case !service.Available:
			marker = markerUnavailable
		}
		lines = append(lines, fmt.Sprintf("  %s%s  (%s)", marker, text.Printable(service.Name), text.Printable(service.Project)),
			"        "+text.Printable(service.URL))
	}
	return "\n\n" + strings.Join(lines, "\n")
}

// formatIndexRow is one entry's block of the plain-text twin: its state and
// branch, host, directory, guidance, and every declared
// service with its own state marker.
func formatIndexRow(entry IndexEntry, dockerReachable bool) string {
	unchecked := !dockerReachable && entry.State != worktree.StateDirectoryMissing
	services := "    (no services)"
	if len(entry.Services) > 0 {
		lines := make([]string, len(entry.Services))
		for i, service := range entry.Services {
			marker := markerAvailable
			switch {
			case entry.State == worktree.StateDirectoryMissing:
				marker = markerGone
			case unchecked:
				marker = markerUnchecked
			case !service.Available:
				marker = markerUnavailable
			}
			label := service.Label
			if service.Purpose != "" {
				label = fmt.Sprintf("%s (%s)", service.Label, service.Purpose)
			}
			named := text.Printable(label)
			link := text.Printable(service.URL)
			line := fmt.Sprintf("    %s%s %s", marker, text.PadEnd(named, 28), link)
			if text.JSLen(line) <= textWidth {
				lines[i] = line
				continue
			}
			// The URL is the one thing worth double-clicking, so it never
			// shares a line it would be wrapped out of; it is indented past
			// the names so a continuation cannot be read as another
			// service.
			wrapped := strings.Split(wrapText(named, textWidth-8), "\n")
			first, rest := wrapped[0], wrapped[1:]
			parts := make([]string, 0, len(rest)+2)
			parts = append(parts, "    "+marker+first)
			// Continuations sit at the URL's column, never at the column a
			// service name starts in, where they would read as another
			// service.
			for _, part := range rest {
				parts = append(parts, "        "+part)
			}
			parts = append(parts, "        "+link)
			lines[i] = strings.Join(parts, "\n")
		}
		services = strings.Join(lines, "\n")
	}

	described := DescribeBranch(entry.Branch)
	parts := []string{
		// The status leads: a branch name is one unbreakable token, so
		// trailing it would push the state off an eighty-column terminal.
		fmt.Sprintf("  [%s]  %s", entry.State, text.Printable(described.Text)),
		indented("    host      ", text.Printable(entry.Host)),
		// A path, like a host or a URL, is left whole however long it is:
		// each is a single token, there to be copied.
		checkoutLine(entry),
	}
	switch entry.State {
	case worktree.StateDirectoryMissing:
		// The same remedy the page offers, for whoever is reading this over
		// SSH. One command, never folded: it is there to be copied.
		parts = append(parts, fmt.Sprintf("    fix       %s worktree remove %s", brand.Name, text.Printable(entry.Slug)))
	case worktree.StateRemoving:
		parts = append(parts, fmt.Sprintf("    finish    %s worktree remove %s", brand.Name, text.Printable(entry.Slug)))
	case worktree.StateUnknown:
		if entry.Hint != "" {
			parts = append(parts, indented("    why       ", text.Printable(entry.Hint)))
		}
	}
	parts = append(parts, services)
	return strings.Join(parts, "\n")
}

// checkoutLine is the text twin's directory line: "-" when nothing recorded
// a root, otherwise the root compacted under the current home.
func checkoutLine(entry IndexEntry) string {
	if entry.Root == "" {
		return "    directory -"
	}
	return "    directory " + text.Printable(compactPath(entry.Root, homeDir()))
}

// indented is a labelled line whose continuation lines sit under the value,
// not the label.
func indented(label, value string) string {
	wrapped := strings.Split(wrapText(value, textWidth-text.JSLen(label)), "\n")
	first, rest := wrapped[0], wrapped[1:]
	lines := make([]string, 0, len(rest)+1)
	lines = append(lines, label+first)
	pad := strings.Repeat(" ", text.JSLen(label))
	for _, part := range rest {
		lines = append(lines, pad+part)
	}
	return strings.Join(lines, "\n")
}
